SELECT AVG(fare) AS avg_fare_completed_rides
FROM rides
WHERE status = 'completed';

SELECT COUNT(*) AS rider_count
FROM users
WHERE user_type = 'rider' AND city = 'Toronto';

SELECT SUM(amount) AS total_completed_payment_amount
FROM payments
WHERE payment_status = 'completed';

SELECT COUNT(*) AS cancelled_rides_count
FROM rides
WHERE status = 'cancelled';

SELECT
    ROUND(
        100.0 * COUNT(*) FILTER (WHERE payment_status = 'failed') / COUNT(*),
        2
    ) AS failed_payment_percentage
FROM payments;

SELECT
  ROUND(
    100.0 * COUNT(*) FILTER (WHERE payment_status = 'refunded') / COUNT(*),
    2
  ) AS refunded_percentage
FROM payments;

SELECT COUNT(*) AS driver_count
FROM users
WHERE user_type = 'driver';

SELECT COUNT(*) AS active_driver_count
FROM users
WHERE user_type = 'driver' AND is_active = true;

SELECT COUNT(*) AS ride_requests_2026
FROM rides
WHERE EXTRACT(YEAR FROM requested_at) = 2026;

SELECT COUNT(*) AS driver_count
FROM users
WHERE user_type = 'driver' AND city = 'Montreal';

SELECT COUNT(*) AS inactive_riders
FROM users
WHERE user_type = 'rider' AND is_active = FALSE;
